"""User-authored agent configuration.

A project's ``agent.yml`` carries the prompt-facing agent identity in an
``agent:`` wrapper (``id``, ``language``, ``persona``, and optionally ``voice``)
alongside top-level prompt tuning (``rules``, ``conversation``,
``skill_retrieval``, ``orchestrator``).
It is parsed once into a frozen :class:`AgentSpec` at model load by
``rasa.mantle.model_archive.bootstrap`` (from the packaged snapshot's
``agent.yml``).
"""

from __future__ import annotations

import math
import time
from pathlib import Path
from typing import Any, Mapping, Optional, Tuple

import pydantic
import structlog
from duoname import duoname
from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

from rasa.core.information_retrieval.faiss import (
    DEFAULT_CHUNK_OVERLAP,
    DEFAULT_CHUNK_SIZE,
)
from rasa.exceptions import ValidationError
from rasa.mantle.config.builtin_tool_constraints import BuiltinToolConstraints
from rasa.mantle.config.preconditions import PreconditionBinding
from rasa.shared.core.constants import GLOBAL_SILENCE_TIMEOUT_DEFAULT_VALUE
from rasa.shared.utils.yaml import read_yaml_file, write_yaml

structlogger = structlog.get_logger()

DEFAULT_TOOL_TIMEOUT_SECONDS = 10.0
"""Default wall-clock limit for custom ``@tool`` and MCP tool calls."""

DEFAULT_SILENCE_TIMEOUT_RETRIES = 3
"""Check-ins allowed before the engine hangs up on consecutive silence."""

REFERENCES_EMBEDDINGS_DEFAULT_HINT = (
    "Declare it, or clear knowledge_answering.embeddings to use the built-in embedder."
)
"""Appended to errors about an unknown ``knowledge_answering.embeddings`` group.

The orchestrator has no built-in fallback, so its errors must not carry it.
"""


def resolve_tool_timeout(tool_timeout: Optional[float]) -> float:
    """Return the effective agent ``tool_timeout``, applying the Mantle default."""
    if tool_timeout is None:
        return DEFAULT_TOOL_TIMEOUT_SECONDS
    if not math.isfinite(tool_timeout) or tool_timeout <= 0:
        raise ValueError("`tool_timeout` must be a finite number greater than 0.")
    return float(tool_timeout)


_AGENT_KEY = "agent"
_CONVERSATION_KEY = "conversation"
_ORCHESTRATOR_KEY = "orchestrator"
_PRECONDITIONS_KEY = "preconditions"
_BEFORE_END_KEY = "before_end"
DEFAULT_AGENT_LANGUAGE = "en"
_MISSING_PERSONA_CODE = "config.agent.missing_persona"
_MISSING_AGENT_SECTION_CODE = "config.agent.missing_section"
_MISSING_ORCHESTRATOR_CODE = "config.agent.missing_orchestrator"
_INVALID_AGENT_SECTION_CODE = "config.agent.invalid_section"


class AckExample(BaseModel):
    """One user-message → acknowledgement example for the ack prompt section."""

    model_config = ConfigDict(frozen=True, extra="ignore")

    user: str = ""
    ack: str = ""


class FillersConfig(BaseModel):
    """The short line spoken before a tool runs."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    enabled: bool | None = None
    """Whether the acknowledgement section and reminder are included.

    ``None`` (omitted in agent.yml) → enabled on voice turns, disabled on text.
    Explicit ``true``/``false`` overrides for both modalities.
    """

    instructions: str = ""
    """System-prompt rule for the pre-tool line (empty → built-in paragraph)."""

    reminder: str = ""
    """System message inserted after the user on the first LLM call.

    Empty → the built-in nudge.
    """

    examples: Tuple[AckExample, ...] = ()
    """Few-shot lines rendered under the filler instructions."""


class AgentPromptConfig(BaseModel):
    """Prompt settings that are not the pre-tool line or a channel style."""

    model_config = ConfigDict(frozen=True, extra="ignore")

    routing_no_active_skill: str = ""
    """Extra routing guidance appended when no skill is active."""


def resolve_ack_enabled(fillers: FillersConfig, *, is_voice: bool) -> bool:
    """Return whether the pre-tool line is enabled for this turn.

    When ``fillers.enabled`` is unset (``None``), defaults to on for voice
    and off for text. An explicit boolean overrides for both modalities.
    """
    if fillers.enabled is not None:
        return fillers.enabled
    return is_voice


class VoiceSettingsConfig(BaseModel):
    """Top-level ``voice:`` block in ``agent.yml``.

    ``silence_timeout`` replaces ``interaction_handling.global_silence_timeout``
    from ``endpoints.yml``. A voice channel's own ``silence_timeout`` overrides it.
    """

    model_config = ConfigDict(frozen=True, extra="forbid", hide_input_in_errors=True)

    silence_timeout: float = Field(
        default=GLOBAL_SILENCE_TIMEOUT_DEFAULT_VALUE,
        gt=0,
        allow_inf_nan=False,
    )


class AgentVoiceConfig(BaseModel):
    """Optional voice settings from ``agent.voice`` (stored for forward compat).

    Parsed and retained on :class:`AgentSpec` so projects can author voice
    settings before voice runtime lands. No ASR/TTS or channel behaviour is
    wired here.
    """

    model_config = ConfigDict(frozen=True, extra="ignore")

    enabled: bool = False
    sample_rate: Optional[int] = None
    input_mime_type: str = ""
    output_encoding: str = ""
    asr: str = ""
    tts: str = ""


class ReferenceChunkingConfig(BaseModel):
    """Configure how reference documents are split before embedding."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    chunk_size: int = Field(default=DEFAULT_CHUNK_SIZE, gt=0)
    """Maximum number of characters in a reference chunk."""

    chunk_overlap: int = Field(default=DEFAULT_CHUNK_OVERLAP, ge=0)
    """Number of characters shared by adjacent reference chunks."""

    @model_validator(mode="after")
    def validate_chunk_overlap(self) -> "ReferenceChunkingConfig":
        """Ensure overlap leaves room for new content in each chunk."""
        if self.chunk_overlap >= self.chunk_size:
            raise ValueError("`chunk_overlap` must be smaller than `chunk_size`.")
        return self


class KnowledgeAnsweringConfig(BaseModel):
    """How the agent answers from retrieved chunks.

    A skill may override the house style with its own
    ``knowledge_answering.instructions``. Empty instructions keep the built-in
    search bullet and add no extra paragraph.
    """

    model_config = ConfigDict(frozen=True, extra="forbid")

    instructions: str = ""
    """How to write an answer from retrieved chunks.

    Empty keeps the built-in search bullet and adds no extra paragraph.
    """

    embeddings: str = ""
    """Model-group id (from ``integrations.yml`` ``model_groups``) used to embed the
    local documents. Empty → the built-in default embeddings (OpenAI)."""

    chunking: ReferenceChunkingConfig = ReferenceChunkingConfig()
    """Index-time recursive character chunking configuration."""

    top_k: int = Field(default=4, gt=0)
    """How many chunks the local index returns. Omitted keeps four."""


class SkillRetrievalConfig(BaseModel):
    """Configure semantic skill retrieval."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    active: bool = False
    """Whether semantic skill retrieval is enabled.

    Omitting ``skill_retrieval`` or this key leaves retrieval off. Set
    ``true`` to opt in. An index is written and the catalogue is filtered
    only when startable skills exceed ``num_skills``.
    """

    num_skills: int = Field(default=20, ge=1)
    """Maximum number of skills returned by semantic search.

    At least 1. To keep the full catalogue, set ``active`` to false.
    """

    turns_to_embed: int = Field(default=1, ge=1)
    """How many recent utterance lines go into the search query.

    ``1`` (default) embeds only the current user message. Values greater
    than ``1`` take the last N ``UserUttered`` / ``BotUttered`` transcript
    lines — not user turns only — and send that text to the embedding
    provider.
    """

    should_embed_memory: bool = True
    """Whether skill memory field schemas are included in indexed documents."""

    embeddings: str = ""
    """Model-group id used to embed skill documents and user queries."""


class OrchestratorConfig(BaseModel):
    """Engine-owned settings from the ``orchestrator:`` block in agent.yml."""

    model_config = ConfigDict(frozen=True, extra="forbid", hide_input_in_errors=True)

    model_group: str = Field(min_length=1)
    """Model-group id defined under ``model_groups`` in ``integrations.yml``."""

    text_rules: str = ""
    """Channel rules for text turns (empty → built-in block)."""

    voice_rules: str = ""
    """Channel rules for voice turns (empty → built-in block)."""

    max_prompt_tokens: int | None = Field(default=None, gt=0)
    """Optional prompt budget; omitted values use the engine default."""

    preconditions: dict[str, PreconditionBinding] = Field(default_factory=dict)
    """Semantic precondition bindings keyed by name."""

    tool_constraints: BuiltinToolConstraints = Field(default_factory=dict)
    """Optional ``enabled``, ``invoke_when`` and ``requires_confirmation`` levers.

    ``requires_confirmation`` applies to ``cancel`` only. Omitted means
    default offer rules and immediate cancel.
    """

    @field_validator("model_group")
    @classmethod
    def _strip_non_blank_model_group(cls, value: str) -> str:
        """Reject a blank model-group id and trim surrounding whitespace."""
        stripped = value.strip()
        if not stripped:
            raise ValueError("must be a non-empty string")
        return stripped


class AgentSpec(BaseModel):
    """User-authored agent identity parsed from the `agent.yml`."""

    model_config = ConfigDict(frozen=True, extra="ignore", hide_input_in_errors=True)

    id: str = ""
    """Stable agent identifier from ``agent.id`` (packaged as model metadata)."""

    language: str = ""
    """Primary conversation language from ``agent.language``."""

    persona: str = ""
    """Free-text persona prepended to every system prompt."""

    voice: Optional[AgentVoiceConfig] = None
    """Optional ``agent.voice`` block retained for forward compatibility."""

    silence_timeout: float = Field(
        default=GLOBAL_SILENCE_TIMEOUT_DEFAULT_VALUE,
        gt=0,
        allow_inf_nan=False,
    )
    """Seconds from top-level ``voice.silence_timeout``. The channel value wins."""

    name: str = ""
    description: str = ""

    rules: Tuple[str, ...] = ()
    """Agent-wide conversation rules rendered as a bullet list."""

    fillers: FillersConfig = FillersConfig()
    """Pre-tool line: enabled, instructions, reminder, and examples."""

    prompts: AgentPromptConfig = AgentPromptConfig()
    """Prompt settings that stay under ``prompts``."""

    knowledge_answering: KnowledgeAnsweringConfig = KnowledgeAnsweringConfig()
    """How answers from retrieved passages are written."""

    skill_retrieval: SkillRetrievalConfig = SkillRetrievalConfig()
    """Semantic skill retrieval configuration."""

    before_end: Tuple[str, ...] = ()
    """Skill names that should complete before the conversation ends.

    Authored as ``conversation.before_end`` in agent.yml and flattened here.
    """

    tool_timeout: Optional[float] = Field(
        default=None,
        gt=0,
        allow_inf_nan=False,
        description=(
            "Default wall-clock timeout in seconds for custom ``@tool`` "
            "functions. Imported MCP tools use this when a server omits "
            "``tool_timeout`` in integrations.yml; per-server values override."
        ),
    )

    orchestrator: OrchestratorConfig
    """Required model-group reference and precondition bindings.

    Every agent names the group that serves its turns, so there is no default.
    """

    preconditions: dict[str, PreconditionBinding] = Field(default_factory=dict)
    """Flattened ``orchestrator.preconditions`` for runtime and validation."""

    @model_validator(mode="before")
    @classmethod
    def _flatten_conversation_section(cls, data: Any) -> Any:
        """Lift supported ``conversation`` fields into the internal flat model."""
        if not isinstance(data, dict):
            return data
        conversation = data.get(_CONVERSATION_KEY)
        if not isinstance(conversation, dict):
            return data
        flattened = {
            key: conversation[key]
            for key in (_BEFORE_END_KEY,)
            if key not in data and key in conversation and conversation[key] is not None
        }
        return {**data, **flattened}

    @model_validator(mode="before")
    @classmethod
    def _flatten_orchestrator_section(cls, data: Any) -> Any:
        """Lift ``orchestrator.preconditions`` to the ``preconditions`` field."""
        if not isinstance(data, dict):
            return data
        orchestrator = data.get(_ORCHESTRATOR_KEY)
        if isinstance(orchestrator, dict):
            preconditions = orchestrator.get(_PRECONDITIONS_KEY)
            if preconditions is not None:
                data = {**data, _PRECONDITIONS_KEY: preconditions}
        return data


def generate_agent_id() -> str:
    """Return a unique agent identifier in the same shape as v1 ``assistant_id``.

    Format: ``YYYYMMDD-HHMMSS-<duoname>`` (see
    :func:`rasa.cli.validation.config_path_validation.validate_assistant_id_in_config`).
    """
    time_format = "%Y%m%d-%H%M%S"
    return f"{time.strftime(time_format)}-{duoname()}"


def normalize_agent_identity_fields(
    agent_section: Mapping[str, Any],
) -> dict[str, Any]:
    """Apply agent identity defaults and mandatory-field checks.

    * ``id`` — generated when absent or blank (same pattern as v1 ``assistant_id``).
    * ``language`` — defaults to :data:`DEFAULT_AGENT_LANGUAGE` when absent or blank.
    * ``persona`` — required; must be a non-empty string.

    Args:
        agent_section: Raw ``agent:`` mapping from ``agent.yml``.

    Returns:
        A copy of *agent_section* with normalized ``id`` and ``language``.

    Raises:
        ValidationError: When ``persona`` is missing or blank.
    """
    normalized = dict(agent_section)

    agent_id = normalized.get("id")
    if not isinstance(agent_id, str) or not agent_id.strip():
        normalized["id"] = generate_agent_id()

    language = normalized.get("language")
    if not isinstance(language, str) or not language.strip():
        normalized["language"] = DEFAULT_AGENT_LANGUAGE

    persona = normalized.get("persona")
    if not isinstance(persona, str) or not persona.strip():
        raise ValidationError(
            code=_MISSING_PERSONA_CODE,
            event_info=(
                "Invalid agent configuration in agent.yml: "
                "'agent.persona' must be a non-empty string."
            ),
        )

    return normalized


def _agent_section_from_config(
    config_data: Mapping[str, Any],
) -> Mapping[str, Any]:
    """Return the normalized ``agent:`` mapping from *config_data*.

    Raises:
        ValidationError: When the ``agent:`` wrapper is absent or not a mapping,
            or when ``agent.persona`` is missing or blank.
    """
    if _AGENT_KEY not in config_data:
        raise ValidationError(
            code=_MISSING_AGENT_SECTION_CODE,
            event_info=(
                "Invalid agent configuration in agent.yml: "
                "an 'agent:' section is required."
            ),
        )
    agent_section = config_data.get(_AGENT_KEY)
    if not isinstance(agent_section, Mapping):
        raise ValidationError(
            code=_INVALID_AGENT_SECTION_CODE,
            event_info=(
                "Invalid agent configuration in agent.yml: "
                "'agent:' must be a mapping."
            ),
        )
    return normalize_agent_identity_fields(agent_section)


def ensure_agent_identity_in_agent_yml(agent_path: Path) -> None:
    """Ensure ``agent.yml`` has a unique ``agent.id``; require ``agent.persona``.

    When ``agent.id`` is missing or blank, logs a warning, generates a unique id,
    and writes it back to *agent_path*. ``agent.language`` is not written — the
    ``en`` default is applied at parse time only.

    Args:
        agent_path: Path to the project's ``agent.yml``.

    Raises:
        ValidationError: When the file is not a mapping, the ``agent:`` block is
            missing or not a mapping, or ``agent.persona`` is absent/blank.
    """
    config_data = read_yaml_file(str(agent_path), expand_env_vars=False)
    if not isinstance(config_data, Mapping):
        raise ValidationError(
            code=_INVALID_AGENT_SECTION_CODE,
            event_info=f"Invalid agent configuration in {agent_path.name}: "
            "file must contain a YAML mapping.",
        )

    agent_section = config_data.get(_AGENT_KEY, {})
    original_id = (
        agent_section.get("id") if isinstance(agent_section, Mapping) else None
    )
    normalized = _agent_section_from_config(config_data)

    if not isinstance(original_id, str) or not original_id.strip():
        structlogger.warn(
            "mantle.agent.missing_agent_id_autogenerated",
            agent_yml=str(agent_path),
            generated_id=normalized["id"],
            event_info=(
                f"The agent config '{agent_path}' is missing a unique value for "
                f"'agent.id'. Proceeding with generated id "
                f"'{normalized['id']}' and overwriting 'agent.id' in the file."
            ),
        )
        write_yaml(
            data={**dict(config_data), _AGENT_KEY: normalized},
            target=str(agent_path),
            should_preserve_key_order=True,
        )


def _require_orchestrator_model_group(config_data: Mapping[str, Any]) -> None:
    """Require ``orchestrator.model_group`` when parsing ``agent.yml``.

    Checked before the Pydantic parse so the builder sees a file-level message
    naming the key, the same way a missing ``agent.persona`` is reported.

    Raises:
        ValidationError: When ``orchestrator:`` is missing or not a mapping, or
            ``orchestrator.model_group`` is missing or blank.
    """
    if _ORCHESTRATOR_KEY not in config_data:
        raise ValidationError(
            code=_MISSING_ORCHESTRATOR_CODE,
            event_info=(
                "Invalid agent configuration in agent.yml: "
                "'orchestrator.model_group' is required."
            ),
        )
    orchestrator = config_data[_ORCHESTRATOR_KEY]
    if not isinstance(orchestrator, Mapping):
        raise ValidationError(
            code=_INVALID_AGENT_SECTION_CODE,
            event_info=(
                "Invalid agent configuration in agent.yml: "
                "'orchestrator:' must be a mapping."
            ),
        )
    model_group = orchestrator.get("model_group")
    if not isinstance(model_group, str) or not model_group.strip():
        raise ValidationError(
            code=_MISSING_ORCHESTRATOR_CODE,
            event_info=(
                "Invalid agent configuration in agent.yml: "
                "'orchestrator.model_group' must be a non-empty string."
            ),
        )


def _silence_timeout_from_config(config_data: Mapping[str, Any]) -> Optional[float]:
    """Return ``voice.silence_timeout`` when a top-level ``voice:`` block is present."""
    if "voice" not in config_data:
        return None
    voice = config_data["voice"]
    if not isinstance(voice, Mapping):
        raise ValidationError(
            code=_INVALID_AGENT_SECTION_CODE,
            event_info=(
                "Invalid agent configuration in agent.yml: "
                "'voice:' must be a mapping."
            ),
        )
    return VoiceSettingsConfig.model_validate(voice).silence_timeout


def _agent_spec_payload(config_data: Mapping[str, Any]) -> dict[str, Any]:
    """Build the :class:`AgentSpec` field dict from a top-level agent.yml mapping."""
    data = dict(config_data)
    agent_section = dict(_agent_section_from_config(data))
    _require_orchestrator_model_group(data)

    payload: dict[str, Any] = {
        "id": agent_section.get("id", ""),
        "language": agent_section.get("language", ""),
        "persona": agent_section.get("persona", ""),
    }
    if "voice" in agent_section:
        payload["voice"] = agent_section.get("voice")
    silence_timeout = _silence_timeout_from_config(data)
    if silence_timeout is not None:
        payload["silence_timeout"] = silence_timeout

    for key in (
        "name",
        "description",
        "rules",
        "prompts",
        _CONVERSATION_KEY,
        _ORCHESTRATOR_KEY,
        "knowledge_answering",
        "fillers",
        "skill_retrieval",
        "tool_timeout",
    ):
        if key in data:
            payload[key] = data[key]
    if _BEFORE_END_KEY in data:
        payload[_BEFORE_END_KEY] = data[_BEFORE_END_KEY]
    return payload


def _format_pydantic_errors(error: pydantic.ValidationError) -> str:
    """Flatten pydantic errors without including submitted field values.

    ``str(ValidationError)`` echoes ``input_value``. A builder who pastes
    ``api_key`` under ``orchestrator`` would otherwise see that secret in the
    validation message.
    """
    parts: list[str] = []
    for issue in error.errors(include_input=False):
        location = ".".join(str(part) for part in issue["loc"]) or "agent"
        parts.append(f"'{location}': {issue['msg']}")
    return "; ".join(parts)


def agent_spec_from_config(config_data: Optional[Mapping[str, Any]]) -> AgentSpec:
    """Parse the agent identity from a top-level agent.yml mapping.

    When an ``agent:`` block is present, ``agent.id`` is auto-generated if
    missing, ``agent.language`` defaults to ``en``, and ``agent.persona`` is
    required. A top-level ``orchestrator:`` block with ``model_group`` is
    required. Prompt tuning keys (``rules``, ``fillers``, ``conversation``)
    remain at the top level of agent.yml. Skill precondition bindings are read
    from ``orchestrator.preconditions``. Unknown keys under ``orchestrator`` are
    rejected. Unrelated top-level keys are ignored. A missing
    *config_data* (no ``agent.yml``) or any mapping without an ``agent:`` block
    raises a fail-fast :class:`ValidationError`.
    """
    if config_data is None:
        raise ValidationError(
            code="config.agent.missing_agent_yml_file",
            event_info="You must provide a top-level agent.yml mapping.",
        )

    try:
        return AgentSpec.model_validate(_agent_spec_payload(config_data))
    except ValidationError:
        raise
    except pydantic.ValidationError as error:
        raise ValidationError(
            code=_INVALID_AGENT_SECTION_CODE,
            event_info=(
                "Invalid agent configuration in agent.yml: "
                f"{_format_pydantic_errors(error)}"
            ),
        ) from error
